CREATE TABLE "AnalyticsEvent" ("id" TEXT NOT NULL, "eventKey" TEXT NOT NULL, "type" TEXT NOT NULL, "orderId" TEXT, "valueCents" INTEGER, "currency" TEXT NOT NULL DEFAULT 'USD', "isDemo" BOOLEAN NOT NULL DEFAULT false, "status" TEXT NOT NULL DEFAULT 'INTERNAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AnalyticsEvent_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "AnalyticsEvent_eventKey_key" ON "AnalyticsEvent"("eventKey"); CREATE INDEX "AnalyticsEvent_type_createdAt_idx" ON "AnalyticsEvent"("type", "createdAt");